/**
 * Same-task trend over photo records: for each region, only photos whose
 * expression exercises that region contribute (e.g. mouth asymmetry across
 * the smile photos), excluded regions are skipped, and several photos of the
 * same task on one day are averaged. Pure.
 */
import type { StillRegion } from '../core';
import type { PhotoRecord } from '../data/types';
import { TREND_REGIONS } from './library';

export const TREND_TASK_LABEL: Record<StillRegion, string> = { mouth: '웃기', brow: '이마 올리기', eye: '눈 감기', midface: '코 찡그리기' };
export const TREND_ORDER: readonly StillRegion[] = ['mouth', 'brow', 'eye'];

export interface TrendLine {
  region: StillRegion;
  /** Day → asymmetry in mm (affected side worse, floored at 0). */
  points: { x: number; y: number }[];
}

export function trendLines(records: readonly PhotoRecord[]): TrendLine[] {
  const out: TrendLine[] = [];
  for (const r of TREND_ORDER) {
    const byDay = new Map<number, number[]>();
    for (const p of records) {
      if (!p.analysis || p.day === null || !TREND_REGIONS[p.expression].includes(r) || p.analysis.regions[r].excluded) continue;
      byDay.set(p.day, [...(byDay.get(p.day) ?? []), Math.max(0, p.analysis.regions[r].diffMm)]);
    }
    const points = [...byDay.entries()].sort((a, b) => a[0] - b[0]).map(([x, ys]) => ({ x, y: ys.reduce((s, y) => s + y, 0) / ys.length }));
    if (points.length) out.push({ region: r, points });
  }
  return out;
}

export interface TrendSummary {
  region: StillRegion;
  first: { day: number; mm: number };
  last: { day: number; mm: number };
}

/** First → last value of each region followed on at least two days. */
export function trendSummary(records: readonly PhotoRecord[]): TrendSummary[] {
  return trendLines(records)
    .filter((l) => l.points.length >= 2)
    .map((l) => ({
      region: l.region,
      first: { day: l.points[0]!.x, mm: l.points[0]!.y },
      last: { day: l.points[l.points.length - 1]!.x, mm: l.points[l.points.length - 1]!.y },
    }));
}
