/**
 * Installing the app to the home screen. Android/desktop Chrome fires `beforeinstallprompt` (kept here so a
 * button can show the prompt later); iOS Safari has no prompt and needs 공유 → 홈 화면에 추가. Imported at start-up
 * (main.tsx) so the event is never missed.
 */
import { useEffect, useState } from 'preact/hooks';

interface InstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

let deferred: InstallPromptEvent | null = null;
const listeners = new Set<() => void>();
const notify = () => listeners.forEach((l) => l());

if (typeof window !== 'undefined') {
  addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferred = e as InstallPromptEvent;
    notify();
  });
  addEventListener('appinstalled', () => {
    deferred = null;
    notify();
  });
}

export const isStandalone = (): boolean =>
  (typeof matchMedia === 'function' && matchMedia('(display-mode: standalone)').matches) ||
  (navigator as Navigator & { standalone?: boolean }).standalone === true;

export const isIOS = (): boolean =>
  /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

export function useInstall() {
  const [, tick] = useState(0);
  useEffect(() => {
    const l = () => tick((t) => t + 1);
    listeners.add(l);
    return () => void listeners.delete(l);
  }, []);
  return {
    installed: isStandalone(),
    canPrompt: !!deferred,
    ios: isIOS(),
    /** Shows the browser's install dialog; true when the user accepted. */
    async prompt(): Promise<boolean> {
      if (!deferred) return false;
      const e = deferred;
      await e.prompt();
      const r = await e.userChoice;
      deferred = null;
      notify();
      return r.outcome === 'accepted';
    },
  };
}
