import { useState } from 'preact/hooks';
import type { Side } from '../../core';
import { FEATURES } from '../../config';
import { CONSENT_VERSION, DISCLAIMER_POINTS, EXPECTED_FLAGS_ADVICE, INTENDED_USE, RED_FLAGS, RED_FLAG_ADVICE } from '../../data/consent';
import { localDate, uid } from '../../data/db';
import { actions } from '../../data/store';
import { deviceRole, setDeviceRole } from '../../data/mode';
import type { Etiology, Profile, UserRole } from '../../data/types';
import { AppBar, Notice, Segmented } from '../components/common';
import { ModePinForm } from '../components/ModePin';
import { Icon } from '../icons';
import { ETIOLOGY_LABEL } from '../labels';
import { ROLE_LABEL, availableRoles } from '../role';

export function ProfileFields({ value, onChange }: { value: ProfileDraft; onChange: (v: ProfileDraft) => void }) {
  const set = <K extends keyof ProfileDraft>(k: K, v: ProfileDraft[K]) => onChange({ ...value, [k]: v });
  return (
    <div class="stack" style={{ gap: '14px' }}>
      <div class="field">
        <span>마비된 쪽 (본인 기준)</span>
        <Segmented<Side>
          label="마비된 쪽"
          value={value.affectedSide}
          onChange={(v) => set('affectedSide', v)}
          options={[
            { value: 'left', label: '왼쪽 얼굴' },
            { value: 'right', label: '오른쪽 얼굴' },
          ]}
        />
      </div>
      <label class="field">
        <span>증상이 처음 나타난 날</span>
        <input
          class="input"
          type="date"
          max={localDate()}
          value={value.onsetDate}
          onInput={(e) => set('onsetDate', (e.target as HTMLInputElement).value)}
        />
      </label>
      <label class="field">
        <span>진단받은 원인</span>
        <select class="input" value={value.etiology} onChange={(e) => set('etiology', (e.target as HTMLSelectElement).value as Etiology)}>
          {(Object.keys(ETIOLOGY_LABEL) as Etiology[]).map((k) => (
            <option value={k}>{ETIOLOGY_LABEL[k]}</option>
          ))}
        </select>
      </label>
      <label class="field">
        <span>부를 이름 (선택)</span>
        <input class="input" maxLength={20} value={value.nickname} onInput={(e) => set('nickname', (e.target as HTMLInputElement).value)} />
      </label>
      <label class="field">
        <span>출생 연도 (선택)</span>
        <input
          class="input"
          type="number"
          inputMode="numeric"
          min={1900}
          max={new Date().getFullYear()}
          value={value.birthYear ?? ''}
          onInput={(e) => {
            const n = parseInt((e.target as HTMLInputElement).value, 10);
            set('birthYear', Number.isFinite(n) ? n : null);
          }}
        />
      </label>
    </div>
  );
}

export type ProfileDraft = Pick<Profile, 'affectedSide' | 'onsetDate' | 'etiology' | 'nickname' | 'birthYear'>;

export function Onboarding({ subject = null }: { subject?: string | null }) {
  const [step, setStep] = useState(0);
  const [flags, setFlags] = useState<Record<string, boolean>>({});
  const [seenDoctor, setSeenDoctor] = useState(false);
  const [draft, setDraft] = useState<ProfileDraft>({
    affectedSide: 'left',
    onsetDate: localDate(),
    etiology: 'bell',
    nickname: subject ?? '',
    birthYear: null,
  });
  const [consent, setConsent] = useState({ understand: false, local: false, research: false });
  const [busy, setBusy] = useState(false);
  const [caseMsg, setCaseMsg] = useState<string | null>(null);
  // Who uses this device: asked once on a new device (not for a research subject's record, whose device already has a
  // mode). Clinician and researcher modes need the institution PIN first (data/mode.ts).
  const [askRole] = useState(() => !subject && availableRoles().length > 1 && deviceRole() === null);
  const [role, setRole] = useState<UserRole>('patient');
  const [pinFor, setPinFor] = useState<UserRole | null>(null);
  // A clinic device (clinician or researcher mode) can start from research subject codes instead of its own record.
  const clinicDevice = !subject && FEATURES.researchTools && (askRole ? role : (deviceRole() ?? 'patient')) !== 'patient';
  const anyFlag = Object.values(flags).some(Boolean);

  const finish = async () => {
    const now = new Date().toISOString();
    if (askRole) setDeviceRole(role);
    await actions.saveProfile({
      id: uid(),
      createdAt: now,
      ...draft,
      consent: { version: CONSENT_VERSION, at: now, researchExport: consent.research },
      safetyScreenAt: now,
      voiceGuide: true,
      viewMode: 'mirror',
      ...(askRole ? { role } : {}),
    });
    location.hash = '/';
  };

  return (
    <>
      <AppBar
        title={['시작하기', '안전 확인', '내 정보', '데이터 동의'][step]!}
        sub={`${step + 1} / 4`}
        onBack={step > 0 ? () => setStep(step - 1) : undefined}
      />
      <main class="main bare">
        {step === 0 && (
          <>
            <div class="card accent">
              <div style={{ color: 'var(--accent-ink)', width: '44px', height: '44px' }}>
                <Icon name="face" class="hero-icon" />
              </div>
              <h2>안면마비 회복을 기록하고 관리하세요</h2>
              <p class="small ink2">{INTENDED_USE}</p>
            </div>
            <div class="card tight">
              {DISCLAIMER_POINTS.map((d) => (
                <Notice>
                  <span class="small">{d}</span>
                </Notice>
              ))}
            </div>
            {askRole && (
              <div class="card tight">
                <div class="field">
                  <span>누가 쓰나요</span>
                  <Segmented<UserRole>
                    label="누가 쓰나요"
                    value={pinFor ?? role}
                    onChange={(r) => {
                      if (r === 'patient' || role !== 'patient') {
                        // Back to patient, or between clinician and researcher once the PIN was given.
                        setRole(r);
                        setPinFor(null);
                        if (r !== 'patient') setDeviceRole(r);
                      } else setPinFor(r);
                    }}
                    options={availableRoles().map((r) => ({ value: r, label: r === 'patient' ? '환자 본인' : ROLE_LABEL[r] }))}
                  />
                </div>
                {pinFor ? (
                  <ModePinForm
                    label={ROLE_LABEL[pinFor]}
                    onOk={() => {
                      setDeviceRole(pinFor);
                      setRole(pinFor);
                      setPinFor(null);
                    }}
                    onCancel={() => setPinFor(null)}
                  />
                ) : (
                  <span class="xsmall muted">
                    {role === 'patient'
                      ? '본인 얼굴을 평가하고 재활을 기록합니다. 병원·연구용 기기라면 의료진을 고르세요. 나중에 설정 › 사용 모드에서도 바꿀 수 있습니다.'
                      : FEATURES.researchTools
                        ? `${ROLE_LABEL[role]} 모드입니다. 환자마다 가명 코드로 기록을 따로 만들려면 ‘연구 피험자 코드로 시작’을 누르세요.`
                        : `${ROLE_LABEL[role]} 모드입니다. 추정 등급(HB·Sunnybrook)을 함께 보여 줍니다.`}
                  </span>
                )}
              </div>
            )}
            {clinicDevice && !pinFor && (
              <a class="btn primary block" href="#/subjects">
                <Icon name="clipboard" /> 연구 피험자 코드로 시작
              </a>
            )}
            <button
              class={`btn block ${clinicDevice ? 'ghost' : 'primary'}`}
              disabled={!!pinFor}
              onClick={() => setStep(1)}
            >
              {clinicDevice ? '이 기기 주인의 기록 만들기' : '다음'}
            </button>
            {subject && (
              <Notice tone="warn">
                <span class="small">
                  연구 피험자 <b>{subject}</b>의 기록을 새로 만듭니다. 이름 칸에는 코드만 쓰고 실명은 적지 마세요.
                </span>
              </Notice>
            )}
            {FEATURES.demo && !subject && (
              <button
                class="btn ghost block"
                disabled={busy}
                onClick={async () => {
                  setBusy(true);
                  await actions.loadDemo();
                  location.hash = '/';
                }}
              >
                {busy ? '데모 데이터 만드는 중…' : '데모 데이터로 둘러보기'}
              </button>
            )}
            {FEATURES.demo && !subject && (
              <button
                class="btn ghost block"
                disabled={busy || !!caseMsg}
                onClick={async () => {
                  setCaseMsg('준비 중…');
                  try {
                    await actions.startCaseDemo('kamphuis', (d, t, m) => setCaseMsg(`${m} (${Math.min(d + 1, t)}/${t})`));
                    location.hash = '/';
                  } catch {
                    setCaseMsg(null);
                    alert('사진을 분석하지 못했습니다. 네트워크(모델 다운로드)를 확인하세요.');
                  }
                }}
              >
                <Icon name="image" /> {caseMsg ?? '실제 환자 사진 사례로 둘러보기'}
              </button>
            )}
            <p class="xsmall muted" style={{ textAlign: 'center', margin: '4px 0 0' }}>
              다른 폰·주소에서 쓰던 기록이 있으면 시작한 뒤 설정 → ‘기록 가져오기’로 옮길 수 있습니다.
            </p>
          </>
        )}

        {step === 1 && (
          <>
            <p class="ink2">지금 아래 증상이 있다면 체크해 주세요.</p>
            <div class="card tight">
              {RED_FLAGS.map((f) => (
                <label class="check">
                  <input
                    type="checkbox"
                    checked={!!flags[f.id]}
                    onChange={(e) => setFlags({ ...flags, [f.id]: (e.target as HTMLInputElement).checked })}
                  />
                  <span>{f.text}</span>
                </label>
              ))}
            </div>
            {anyFlag && (
              <div class="card danger">
                <Notice tone="danger">
                  <b>{RED_FLAG_ADVICE}</b>
                </Notice>
                <a class="btn primary block" href="tel:119" style={{ background: 'var(--critical)' }}>
                  <Icon name="phone" /> 119 전화하기
                </a>
                <label class="check">
                  <input type="checkbox" checked={seenDoctor} onChange={(e) => setSeenDoctor((e.target as HTMLInputElement).checked)} />
                  <span class="small">이미 의료진에게 이 증상에 대한 진료를 받았습니다.</span>
                </label>
              </div>
            )}
            <div class="card tight">
              {EXPECTED_FLAGS_ADVICE.map((t) => (
                <Notice tone="warn">
                  <span class="small">{t}</span>
                </Notice>
              ))}
            </div>
            <button class="btn primary block" disabled={anyFlag && !seenDoctor} onClick={() => setStep(2)}>
              {anyFlag ? '진료를 받았으며 계속합니다' : '해당 없음 — 계속'}
            </button>
          </>
        )}

        {step === 2 && (
          <>
            <div class="card">
              <ProfileFields value={draft} onChange={setDraft} />
            </div>
            <p class="xsmall muted">마비된 쪽은 측정의 기준입니다. 거울 속 모습이 아니라 본인 얼굴을 기준으로 선택하세요.</p>
            <button class="btn primary block" disabled={!draft.onsetDate} onClick={() => setStep(3)}>
              다음
            </button>
          </>
        )}

        {step === 3 && (
          <>
            <div class="card tight">
              <label class="check">
                <input
                  type="checkbox"
                  checked={consent.understand}
                  onChange={(e) => setConsent({ ...consent, understand: (e.target as HTMLInputElement).checked })}
                />
                <span class="small">이 앱의 결과가 참고용 추정치이며 의료진의 진단·치료를 대신하지 않음을 이해했습니다. (필수)</span>
              </label>
              <label class="check">
                <input
                  type="checkbox"
                  checked={consent.local}
                  onChange={(e) => setConsent({ ...consent, local: (e.target as HTMLInputElement).checked })}
                />
                <span class="small">
                  얼굴 영상은 저장하지 않고, 얼굴 점 좌표·측정값·운동 기록을 이 기기에만 저장하는 데 동의합니다. (필수)
                </span>
              </label>
              <label class="check">
                <input
                  type="checkbox"
                  checked={consent.research}
                  onChange={(e) => setConsent({ ...consent, research: (e.target as HTMLInputElement).checked })}
                />
                <span class="small">연구 참여 시 비식별 측정 데이터를 파일로 내보내 연구진에게 직접 제공할 수 있습니다. (선택)</span>
              </label>
            </div>
            <p class="xsmall muted">동의 문서 버전 {CONSENT_VERSION}. 설정에서 언제든 모든 데이터를 삭제할 수 있습니다.</p>
            <button class="btn primary block" disabled={!consent.understand || !consent.local} onClick={finish}>
              시작하기
            </button>
          </>
        )}
      </main>
    </>
  );
}
