import type { AnalysisResult, CouplingResult, MuscleResult } from '../core';
import { daysBetween, uid } from './db';
import { seal } from './integrity';
import type { EngineInfo, PatientReport, Profile, SessionRecord, SynkRecord } from './types';

declare const __APP_VERSION__: string;
declare const __BUILD_TIME__: string;

export const APP_INFO = { version: __APP_VERSION__, build: __BUILD_TIME__ };

export async function createSessionRecord(args: {
  analysis: AnalysisResult;
  muscles?: MuscleResult;
  patientReport?: PatientReport;
  profile: Profile;
  mode: SessionRecord['mode'];
  engine: EngineInfo | null;
  camera: string | null;
  at?: Date;
}): Promise<SessionRecord> {
  const at = args.at ?? new Date();
  return seal<SessionRecord>({
    schema: 1,
    id: uid(),
    createdAt: at.toISOString(),
    mode: args.mode,
    daysSinceOnset: daysBetween(args.profile.onsetDate, at),
    profileSnapshot: {
      affectedSide: args.profile.affectedSide,
      onsetDate: args.profile.onsetDate,
      etiology: args.profile.etiology,
    },
    app: APP_INFO,
    engine: args.engine,
    device: {
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'n/a',
      screen: typeof screen !== 'undefined' ? `${screen.width}x${screen.height}@${devicePixelRatio}` : 'n/a',
      camera: args.camera,
    },
    analysis: args.analysis,
    ...(args.muscles ? { muscles: args.muscles } : {}),
    ...(args.patientReport ? { patientReport: args.patientReport } : {}),
  });
}

export async function createSynkRecord(args: {
  result: CouplingResult;
  profile: Profile;
  engine: EngineInfo | null;
  camera: string | null;
  sessionId?: string;
  at?: Date;
}): Promise<SynkRecord> {
  const at = args.at ?? new Date();
  return seal<SynkRecord>({
    schema: 1,
    id: uid(),
    createdAt: at.toISOString(),
    daysSinceOnset: daysBetween(args.profile.onsetDate, at),
    profileSnapshot: { affectedSide: args.profile.affectedSide, onsetDate: args.profile.onsetDate, etiology: args.profile.etiology },
    app: APP_INFO,
    engine: args.engine,
    device: {
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : 'n/a',
      screen: typeof screen !== 'undefined' ? `${screen.width}x${screen.height}@${devicePixelRatio}` : 'n/a',
      camera: args.camera,
    },
    result: args.result,
    ...(args.sessionId ? { sessionId: args.sessionId } : {}),
  });
}
