/**
 * Application state: a tiny observable store over IndexedDB. Assessment
 * records are insert-only; their integrity is verified on load.
 */
import { useEffect, useState } from 'preact/hooks';
import { CONSENT_VERSION } from './consent';
import { forgetBackupMarks, requestPersist } from './backup';
import { clearLock } from './lock';
import { clearDeviceMode } from './mode';
import { listSubjects } from './subjects';
import { db, localDate, uid } from './db';
import type { ImportPlan } from './import';
import { verify } from './integrity';
import type { ClinicianRating, PhotoRecord, Profile, RehabLog, SessionRecord, SynkRecord } from './types';

export interface AppState {
  ready: boolean;
  profile: Profile | null;
  /** Ascending by createdAt. */
  sessions: SessionRecord[];
  /** sessionId → integrity verified. */
  integrity: Record<string, boolean>;
  ratings: ClinicianRating[];
  rehab: RehabLog[];
  /** Single-photo records (bundled cases), ascending by day then photo order. */
  photos: PhotoRecord[];
  /** Synkinesis finder records, ascending by createdAt. */
  synk: SynkRecord[];
}

let state: AppState = { ready: false, profile: null, sessions: [], integrity: {}, ratings: [], rehab: [], photos: [], synk: [] };
const listeners = new Set<() => void>();

function set(patch: Partial<AppState>): void {
  state = { ...state, ...patch };
  listeners.forEach((l) => l());
}

export const getState = (): AppState => state;

export function useApp(): AppState {
  const [, setTick] = useState(0);
  useEffect(() => {
    const l = () => setTick((t) => t + 1);
    listeners.add(l);
    return () => void listeners.delete(l);
  }, []);
  return state;
}

const byDate = (a: SessionRecord, b: SessionRecord) => a.createdAt.localeCompare(b.createdAt);

async function caseOrder(records: PhotoRecord[]): Promise<PhotoRecord[]> {
  const { CASES } = await import('../cases/library');
  const order = new Map(CASES.flatMap((c) => c.photos.map((p, i) => [p.id, i] as const)));
  return records.sort((a, b) => (order.get(a.photoId ?? '') ?? 0) - (order.get(b.photoId ?? '') ?? 0));
}

export const actions = {
  async init(): Promise<void> {
    const [profile, sessions, ratings, rehab, photos, synk] = await Promise.all([
      db.getKv<Profile>('profile'),
      db.getAll<SessionRecord>('sessions'),
      db.getAll<ClinicianRating>('ratings'),
      db.getAll<RehabLog>('rehab'),
      db.getAll<PhotoRecord>('photos'),
      db.getAll<SynkRecord>('synk'),
    ]);
    const integrity: Record<string, boolean> = {};
    await Promise.all([...sessions, ...photos, ...synk].map(async (s) => (integrity[s.id] = await verify(s))));
    set({
      ready: true,
      profile: profile ?? null,
      sessions: sessions.sort(byDate),
      integrity,
      ratings,
      rehab,
      photos: await caseOrder(photos),
      synk: synk.sort((a, b) => a.createdAt.localeCompare(b.createdAt)),
    });
  },

  async saveProfile(p: Profile): Promise<void> {
    await db.setKv('profile', p);
    set({ profile: p });
  },

  async addSession(s: SessionRecord): Promise<void> {
    await db.add('sessions', s);
    set({ sessions: [...state.sessions, s].sort(byDate), integrity: { ...state.integrity, [s.id]: true } });
    // Records now exist: ask the browser not to evict them (silent where the browser decides itself).
    void requestPersist();
  },

  async addSynk(r: SynkRecord): Promise<void> {
    await db.add('synk', r);
    set({ synk: [...state.synk, r], integrity: { ...state.integrity, [r.id]: true } });
  },

  async addRating(r: Omit<ClinicianRating, 'id' | 'createdAt'>): Promise<void> {
    const rating: ClinicianRating = { ...r, id: uid(), createdAt: new Date().toISOString() };
    await db.add('ratings', rating);
    set({ ratings: [...state.ratings, rating] });
  },

  async logRehab(exerciseId: string, durationSec: number, extra: Pick<RehabLog, 'doseStep'> = {}): Promise<RehabLog> {
    const log: RehabLog = { id: uid(), date: localDate(), at: new Date().toISOString(), exerciseId, durationSec, ...extra };
    await db.add('rehab', log);
    set({ rehab: [...state.rehab, log] });
    return log;
  },

  /** Records how an exercise felt (the answer after it); the next dose follows it (rehab/dose.ts). */
  async setFeel(logId: string, feel: NonNullable<RehabLog['feel']>): Promise<void> {
    const log = state.rehab.find((r) => r.id === logId);
    if (!log) return;
    const next = { ...log, feel };
    await db.put('rehab', next);
    set({ rehab: state.rehab.map((r) => (r.id === logId ? next : r)) });
  },

  /**
   * Adds the new records of a checked backup (import.ts planImport) and, if asked, takes over the file's
   * subject details. Insert-only: records already on this device are never replaced. Reloads and re-verifies.
   */
  async importBackup(plan: ImportPlan, adoptSubject: boolean): Promise<void> {
    for (const s of plan.sessions.add) await db.add('sessions', s);
    for (const y of plan.synk.add) await db.add('synk', y);
    for (const r of plan.ratings.add) await db.add('ratings', r);
    for (const r of plan.rehab.add) await db.add('rehab', r);
    if (adoptSubject && plan.subject && state.profile) await db.setKv('profile', { ...state.profile, ...plan.subject });
    await actions.init();
  },

  async deleteAll(): Promise<void> {
    await db.clearAll();
    forgetBackupMarks();
    clearLock();
    // The use mode and its PIN guard the other subjects' records: keep them while any subject remains on the device.
    if (!listSubjects().length) clearDeviceMode();
    set({ profile: null, sessions: [], integrity: {}, ratings: [], rehab: [], photos: [], synk: [] });
  },

  /**
   * Analyses a bundled real-photo case on-device and stores its records.
   * Case records are derived data: an earlier analysis of the same case is replaced.
   */
  async loadCase(caseId: string, onProgress?: (done: number, total: number, msg: string) => void): Promise<void> {
    const { caseById } = await import('../cases/library');
    const { analyzeCase } = await import('../cases/analyze');
    const c = caseById(caseId);
    if (!c) throw new Error(`unknown case ${caseId}`);
    const records = await analyzeCase(c, onProgress);
    for (const old of state.photos.filter((p) => p.caseId === caseId)) await db.delete('photos', old.id);
    for (const r of records) await db.add('photos', r);
    const integrity = { ...state.integrity, ...Object.fromEntries(records.map((r) => [r.id, true])) };
    set({ photos: await caseOrder([...state.photos.filter((p) => p.caseId !== caseId), ...records]), integrity });
  },

  /** Replaces all data with a demo profile built around a real-photo case. */
  async startCaseDemo(caseId: string, onProgress?: (done: number, total: number, msg: string) => void): Promise<void> {
    const { caseById } = await import('../cases/library');
    const c = caseById(caseId);
    if (!c) throw new Error(`unknown case ${caseId}`);
    const lastDay = Math.max(...c.photos.map((p) => p.day ?? 1));
    const onset = new Date();
    onset.setDate(onset.getDate() - (lastDay - 1));
    const now = new Date().toISOString();
    // Analyse first so a failed model load cannot leave an empty demo profile behind.
    const { analyzeCase } = await import('../cases/analyze');
    const records = await analyzeCase(c, onProgress);
    await db.clearAll();
    for (const r of records) await db.add('photos', r);
    set({
      sessions: [],
      ratings: [],
      rehab: [],
      photos: await caseOrder(records),
      integrity: Object.fromEntries(records.map((r) => [r.id, true])),
    });
    await actions.saveProfile({
      id: uid(),
      createdAt: now,
      nickname: '공개 사진 사례',
      birthYear: null,
      affectedSide: c.affectedSide,
      onsetDate: localDate(onset),
      etiology: c.etiology,
      consent: { version: CONSENT_VERSION, at: now, researchExport: false },
      safetyScreenAt: now,
      voiceGuide: true,
      viewMode: 'mirror',
      demoCaseId: c.id,
      demo: true,
    });
  },

  /** Replaces all data with a generated demo history (see demo.ts). */
  async loadDemo(): Promise<void> {
    const { buildDemo } = await import('./demo');
    const demo = await buildDemo();
    await db.clearAll();
    await db.setKv('profile', demo.profile);
    for (const s of demo.sessions) await db.add('sessions', s);
    for (const y of demo.synk) await db.add('synk', y);
    for (const r of demo.rehab) await db.add('rehab', r);
    await actions.init();
  },
};
